60	import org.springframework.security.access.prepost.PreAuthorize;
61	import org.springframework.web.bind.annotation.CrossOrigin;
62	import org.springframework.web.bind.annotation.RequestMapping;
63	import org.springframework.web.bind.annotation.RestController;
64	import org.springframework.web.util.UriComponentsBuilder;
65	
66	import jakarta.transaction.Transactional;
67	
68	/**
69	 * @author Vitaliy Fedoriv
70	 */
71	
72	@RestController
73	@CrossOrigin(exposedHeaders = "errors, content-type")
74	@RequestMapping("/api")
75	public class OwnerRestControllerV1 implements OwnersApi {
76	
77	    private final ClinicService clinicService;
78	
79	    private final OwnerMapper ownerMapper;
80	
81	    private final PetMapper petMapper;
82	
83	    private final VisitMapper visitMapper;
84	
85	    private final HouseholdDuplicateValidator householdDuplicateValidator;
86	
87	    private final PossibleDuplicateOwnerDetector possibleDuplicateOwnerDetector;
88	
89	    private final NamesakeCounter namesakeCounter;
90	
91	    private final HouseholdSizeCounter householdSizeCounter;
92	
93	    private final CityOwnerCapacityValidator cityOwnerCapacityValidator;
94	
95	    private final DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator;
96	
97	    private final OwnerAuditLogger ownerAuditLogger;
98	
99	    private final CustomerCodeDeduplicator customerCodeDeduplicator;
100	
101	    public OwnerRestControllerV1(ClinicService clinicService,
102	                                 OwnerMapper ownerMapper,
103	                                 PetMapper petMapper,
104	                                 VisitMapper visitMapper,
105	                                 HouseholdDuplicateValidator householdDuplicateValidator,
106	                                 PossibleDuplicateOwnerDetector possibleDuplicateOwnerDetector,
107	                                 NamesakeCounter namesakeCounter,
108	                                 HouseholdSizeCounter householdSizeCounter,
109	                                 CityOwnerCapacityValidator cityOwnerCapacityValidator,
110	                                 DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator,
111	                                 OwnerAuditLogger ownerAuditLogger,
112	                                 CustomerCodeDeduplicator customerCodeDeduplicator) {
113	        this.clinicService = clinicService;
114	        this.ownerMapper = ownerMapper;
115	        this.petMapper = petMapper;
116	        this.visitMapper = visitMapper;
117	        this.householdDuplicateValidator = householdDuplicateValidator;
118	        this.possibleDuplicateOwnerDetector = possibleDuplicateOwnerDetector;
119	        this.namesakeCounter = namesakeCounter;
120	        this.householdSizeCounter = householdSizeCounter;
121	        this.cityOwnerCapacityValidator = cityOwnerCapacityValidator;
122	        this.dailyRegistrationCapacityValidator = dailyRegistrationCapacityValidator;
123	        this.ownerAuditLogger = ownerAuditLogger;
124	        this.customerCodeDeduplicator = customerCodeDeduplicator;
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
130	        Collection<Owner> owners;
131	        if (lastName != null) {
132	            owners = this.clinicService.findOwnerByLastName(lastName);
133	        } else {
134	            owners = this.clinicService.findAllOwners();
135	        }
136	        if (owners.isEmpty()) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
145	        Owner owner = this.clinicService.findOwnerById(ownerId);
146	        if (owner == null) {
147	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
148	        }
149	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Override
154	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
155	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
156	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
157	        HttpHeaders headers = new HttpHeaders();
158	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
159	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
160	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
161	        DisposableEmailDomainValidator.validate(owner.getEmail());
162	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
163	        RegistrationDateValidator.validateNotFuture(owner.getRegistrationDate());
164	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
165	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
166	        this.dailyRegistrationCapacityValidator.validateHasCapacity(owner.getRegistrationDate());
167	        owner.setHouseholdId(HouseholdKey.idFor(owner.getLastName(), owner.getPostcode()));
168	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
169	            // An owner sharing a household (same last name and postcode) is otherwise a household
170	            // duplicate. A declared member bypasses this block, and is not a suspected duplicate.
171	            this.householdDuplicateValidator.rejectIfHouseholdExists(owner);
172	            this.possibleDuplicateOwnerDetector.findPossibleDuplicateOf(owner)
173	                .ifPresent(owner::setPossibleDuplicateOf);
174	        }
175	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
176	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
177	        owner.setHouseholdSize(this.householdSizeCounter.count(owner.getHouseholdId()));
178	        String region = RegionResolver.regionFor(owner.getPostcode(), owner.getCity());
179	        String customerCode = CustomerCodeGenerator.generate(region, owner.getTelephone(), owner.getLastName());
180	        owner.setCustomerCode(this.customerCodeDeduplicator.deduplicate(customerCode));
181	        this.clinicService.saveOwner(owner);
182	        owner.setMembershipNumber(MembershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
183	        this.ownerAuditLogger.logCreated(owner);
184	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
185	        headers.setLocation(UriComponentsBuilder.newInstance()
186	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
187	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
193	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
194	        if (currentOwner == null) {
195	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
196	        }
197	        currentOwner.setAddress(ownerFieldsDto.getAddress());
198	        currentOwner.setCity(ownerFieldsDto.getCity());
199	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
200	        currentOwner.setLastName(ownerFieldsDto.getLastName());
201	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
202	        this.clinicService.saveOwner(currentOwner);
203	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Transactional
208	    @Override
209	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
210	        Owner owner = this.clinicService.findOwnerById(ownerId);
211	        if (owner == null) {
212	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	        }
214	        this.clinicService.deleteOwner(owner);
215	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
216	    }
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
221	        Owner owner = this.clinicService.findOwnerById(ownerId);
222	        if (owner == null) {
223	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
224	        }
225	        HttpHeaders headers = new HttpHeaders();
226	        Pet pet = petMapper.toPet(petFieldsDto);
227	        owner.setId(ownerId);
228	        pet.setOwner(owner);
229	        pet.getType().setName(null);
230	        this.clinicService.savePet(pet);
231	        PetDto petDto = petMapper.toPetDto(pet);
232	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
233	            .buildAndExpand(pet.getId()).toUri());
234	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
235	    }
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Override
239	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
240	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
241	        if (currentOwner != null) {
242	            Pet currentPet = this.clinicService.findPetById(petId);
243	            if (currentPet != null) {
244	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
245	                currentPet.setName(petFieldsDto.getName());
246	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
247	                this.clinicService.savePet(currentPet);
248	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
249	            }
250	        }
251	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
252	    }
253	
254	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
255	    @Override
256	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
257	        HttpHeaders headers = new HttpHeaders();
258	        Visit visit = visitMapper.toVisit(visitFieldsDto);
259	        Pet pet = new Pet();
260	        pet.setId(petId);
261	        visit.setPet(pet);
262	        this.clinicService.saveVisit(visit);
263	        VisitDto visitDto = visitMapper.toVisitDto(visit);
264	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
265	            .buildAndExpand(visit.getId()).toUri());
266	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
267	    }
268	
269	
270	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
271	    @Override
272	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
273	        Owner owner = this.clinicService.findOwnerById(ownerId);
274	        if (owner != null) {
275	            Pet pet = owner.getPet(petId);
276	            if (pet != null) {
277	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
278	            }
279	        }
280	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
281	    }
282	}
